function ReactionPanel({room,offset,send}:{room:RoomView;offset:number;send:Send}){
 const prompt=room.reaction!;const [now,setNow]=useState(Date.now()),[pending,setPending]=useState(false);const [choice,setChoice]=useState<Action|undefined>();
 useEffect(()=>{document.querySelector('.reaction-panel')?.scrollIntoView({block:'center'});},[prompt.id]);
 useEffect(()=>{setPending(false);const timer=setInterval(()=>setNow(Date.now()),100);return()=>clearInterval(timer);},[prompt.id]);
 useEffect(()=>{if(!pending)return;const timer=setTimeout(()=>setPending(false),1500);return()=>clearTimeout(timer);},[pending]);
 const remaining=Math.max(0,Math.ceil((prompt.deadline-now-offset)/1000)),name=(id:string)=>cardOf(room.units.find(u=>u.id===id)!.cardId).name;
 function respond(accept:boolean){setPending(true);send('reaction',{reactionId:prompt.id,accept});}
 if(prompt.kind==='extra-action'){const unit=room.units.find(u=>u.id===prompt.actor)!;return <section className="reaction-panel extra-action-panel" role="dialog" aria-modal="false" aria-label="额外行动即时响应"><header><div><p className="eyebrow">MID-TURN DECISION</p><h3>{name(prompt.actor)} · 选择额外行动</h3></div><strong className="reaction-seconds">{remaining}<small>秒</small></strong></header><p>「{skillDisplayName(skillOf(prompt.skill),room.units.find(u=>u.id===prompt.actor))}」已触发，{prompt.restriction==='support'?'本次只能使用非攻击技能。':prompt.restriction==='attack'?'本次必须使用攻击技能。':'请选择技能与目标。'}</p><ActionEditor compact unit={unit} room={room} value={choice} onChange={setChoice} disabled={pending||!remaining} allowedSkills={prompt.allowedSkills}/><div className="reaction-buttons"><button className="button primary" disabled={!choice||pending||!remaining||!prompt.allowedSkills.includes(choice.skill)||Boolean(unit.skillRestrictions?.[choice.skill])} onClick={()=>{setPending(true);send('reaction',{reactionId:prompt.id,action:choice});}}>确认额外行动</button></div><small className="muted">15秒内选择；超时自动使用「{skillDisplayName(skillOf(prompt.defaultAction.skill),unit)}」。本次选择只对你可见，提交后继续结算。</small></section>;}
 return <section className="reaction-panel" role="dialog" aria-modal="false" aria-label="献祭即时响应"><header><div><p className="eyebrow">MID-TURN DECISION</p><h3>是否触发玄武「献祭」？</h3></div><strong className="reaction-seconds">{remaining}<small>秒</small></strong></header><p>{name(prompt.attacker)} 的「{skillDisplayName(skillOf(prompt.skill),room.units.find(u=>u.id===prompt.attacker))}」即将对 {name(prompt.target)} 造成 <b>{prompt.incomingDamage}</b> 点伤害。</p><p>触发后，玄武失去 <b>{prompt.sacrificeCost}</b> 点生命，队友受到 <b>{prompt.allyDamage}</b> 点伤害。</p><div className="reaction-buttons"><button className="button secondary" disabled={pending||!remaining} onClick={()=>respond(false)}>不触发献祭</button><button className="button primary" disabled={pending||!remaining} onClick={()=>respond(true)}>触发献祭</button></div><small className="muted">15秒内选择；超时默认不触发。结算期间已暂停，其他行动不会提前执行。</small></section>;
}



